@import "tailwindcss";

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: #f9fafb;
  color: #111827;
}

/* Hide scrollbar for chip strips */
.scrollbar-hide::-webkit-scrollbar {
  display: none;
}
.scrollbar-hide {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* ── Splash screen (CSS-only animations) ───────────────────── */
@keyframes splashFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes splashFadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes splashFadeOut {
  from { opacity: 1; }
  to   { opacity: 0; }
}
@keyframes splashLogoIn {
  from { opacity: 0; transform: scale(0.8); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes splashRotate {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.splash-overlay        { animation: splashFadeIn 0.3s ease both; }
.splash-overlay.is-out { animation: splashFadeOut 0.2s ease forwards; }

/* Each element stays hidden (fill-mode: both) until its delay elapses. */
.splash-logo    { animation: splashLogoIn   0.5s ease both; animation-delay: 0.2s; }
.splash-name    { animation: splashFadeInUp 0.5s ease both; animation-delay: 0.6s; }
.splash-te      { animation: splashFadeIn   0.5s ease both; animation-delay: 0.9s; }
.splash-tagline { animation: splashFadeIn   0.5s ease both; animation-delay: 1.2s; }
.splash-wheat   { animation: splashRotate   3s   linear infinite; }

@media (prefers-reduced-motion: reduce) {
  .splash-overlay, .splash-overlay.is-out,
  .splash-logo, .splash-name, .splash-te, .splash-tagline, .splash-wheat {
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
  }
}

'use client'

import { useEffect, useRef, useState } from 'react'

// Phases: 'init' before we've decided (avoids SSR/hydration flash),
// 'show' while visible, 'out' during the 0.2s fade, 'done' = unmounted.
type Phase = 'init' | 'show' | 'out' | 'done'

export default function SplashScreen() {
  const [phase, setPhase] = useState<Phase>('init')
  const timers = useRef<ReturnType<typeof setTimeout>[]>([])

  const clearTimers = () => {
    timers.current.forEach(clearTimeout)
    timers.current = []
  }

  useEffect(() => {
    // Show only once per session (per browser tab). A page refresh keeps the
    // flag, so the splash appears on first open only — not on every reload.
    let alreadyShown = false
    try { alreadyShown = sessionStorage.getItem('splash_shown') === 'true' } catch { /* private mode */ }

    if (alreadyShown) {
      setPhase('done')
      return
    }

    try { sessionStorage.setItem('splash_shown', 'true') } catch { /* ignore */ }

    setPhase('show')
    timers.current.push(setTimeout(() => setPhase('out'), 1800))  // 1.8s: start fade out
    timers.current.push(setTimeout(() => setPhase('done'), 2000)) // 2.0s: home visible

    return clearTimers
  }, [])

  // Tapping anywhere during the splash skips it immediately.
  const skip = () => {
    clearTimers()
    setPhase('done')
  }

  if (phase === 'init' || phase === 'done') return null

  return (
    <div
      onClick={skip}
      role="presentation"
      aria-hidden
      className={`splash-overlay fixed inset-0 z-[200] flex flex-col items-center justify-center px-6 text-center select-none ${
        phase === 'out' ? 'is-out' : ''
      }`}
      style={{ backgroundColor: '#1a5c2a' }}
    >
      {/* YFF circle logo */}
      <div className="splash-logo flex items-center justify-center w-24 h-24 rounded-full border-2 border-white">
        <span className="font-black text-white" style={{ fontSize: 32, lineHeight: 1 }}>
          YFF
        </span>
      </div>

      {/* Brand name */}
      <h1 className="splash-name font-bold text-white mt-5" style={{ fontSize: 22 }}>
        YourFamilyFarmer
      </h1>

      {/* Telugu name */}
      <p className="splash-te text-white mt-1" style={{ fontSize: 14 }}>
        యువర్ ఫ్యామిలీ ఫార్మర్
      </p>

      {/* Tagline */}
      <p className="splash-tagline italic text-white mt-4" style={{ fontSize: 16 }}>
        No middlemen. Just farmers.
      </p>

      {/* Slowly rotating wheat */}
      <span className="splash-wheat inline-block mt-6" style={{ fontSize: 24 }} aria-hidden>
        🌾
      </span>
    </div>
  )
}
